message:
The heredoc got messed up because of the shell escaping. Let me write the driver file locally and copy it to the build environment.

<｜｜DSML｜｜>
<parameter=command>
cat > /tmp/test_driver.c << 'EOF'
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int main(int argc, char** argv) {
    if(argc < 2) {
        fprintf(stderr, "usage: %s <input_file>\n", argv[0]);
        return 1;
    }
    FILE* f = fopen(argv[1], "rb");
    if(!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* buf = malloc(sz);
    if(fread(buf, 1, sz, f) != (size_t)sz) { perror("fread"); return 1; }
    fclose(f);
    LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
    return 0;
}
EOF
echo "Driver created locally"
</parameter>
</｜｜DSML｜｜>

